from typing import *
import math

def get_closest_vowel(word):
    """
    Returns the closest vowel from the end of the given word that is not adjacent to another vowel.

    Parameters:
    word (str): The input string consisting only of lowercase and uppercase English letters.

    Returns:
    str: The closest vowel from the end of the word or an empty string if no such vowel exists.
    """
    if len(word) < 3:
        return ''
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'O', 'U', 'I'}
    for i in range(len(word) - 2, 0, -1):
        if word[i] in vowels:
            if word[i + 1] not in vowels and word[i - 1] not in vowels:
                return word[i]
    return ''
